// Catch SIGTERM and drain in-flight requests for zero-downtime deploys.
func main() {
	srv := &http.Server{Addr: ":8080", Handler: mux}

	// ctx is cancelled when SIGINT or SIGTERM arrives.
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	go func() { _ = srv.ListenAndServe() }() // serve in the background
	<-ctx.Done()                             // block until the signal

	// Give in-flight handlers up to 25s to finish, then exit.
	shutCtx, cancel := context.WithTimeout(context.Background(), 25*time.Second)
	defer cancel()
	_ = srv.Shutdown(shutCtx) // stop intake, drain active requests
}
